        "srv01_max_temperature_c": abs(float(fila1["max_temperature_c"]) - ESP1["max_temperature_c"]) < 6e-3,
        "srv01_mean_load": abs(float(fila1["mean_load"]) - ESP1["mean_load"]) < 6e-7,
