        df_antes["requires_review"] = a_bool(df_antes["requires_review"])
    if "timestamp" in df_antes.columns:
        df_antes["timestamp"] = pd.to_datetime(df_antes["timestamp"])
    columnas = ([c for c in COLUMNAS_T3 if c in df_antes.columns]
